import{at as e,it as t,n,vt as r}from"./chunks/framework.BtDTgfNe.js";var i=JSON.parse(`{"title":"Float Literals - v5","description":"Learn about float literals in Textwire","frontmatter":{"title":"Float Literals - v5","description":"Learn about float literals in Textwire"},"headers":[],"relativePath":"v5/language-elements/literals/float.md","filePath":"archive/v5/language-elements/literals/float.md","lastUpdated":1795167968000}`),a={name:`v5/language-elements/literals/float.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="float-literals" tabindex="-1">Float Literals <a class="header-anchor" href="#float-literals" aria-label="Permalink to “Float Literals”">​</a></h1><p>You can use float literals and perform arithmetic operations with them. Example:</p><div class="language-textwire" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">textwire</span><pre class="shiki shiki-themes github-light catppuccin-mocha" style="--shiki-light:#24292e;--shiki-dark:#cdd6f4;--shiki-light-bg:#fff;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#94E2D5;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#89B4FA;">span</span><span style="--shiki-light:#24292E;--shiki-dark:#94E2D5;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-light-font-style:inherit;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">{{</span><span style="--shiki-light:#005CC5;--shiki-dark:#FAB387;"> 1.534</span><span style="--shiki-light:#c62739;--shiki-dark:#CBA6F7;"> + </span><span style="--shiki-light:#005CC5;--shiki-dark:#FAB387;">2.5</span><span style="--shiki-light:#005CC5;--shiki-light-font-style:inherit;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> }}</span><span style="--shiki-light:#24292E;--shiki-dark:#94E2D5;">&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#89B4FA;">span</span><span style="--shiki-light:#24292E;--shiki-dark:#94E2D5;">&gt;</span></span></code></pre></div><h2 id="precision-limit-ieee-754" tabindex="-1">Precision limit (IEEE 754) <a class="header-anchor" href="#precision-limit-ieee-754" aria-label="Permalink to “Precision limit (IEEE 754)”">​</a></h2><p>Floating-point numbers have ~15-17 digit precision. For example, <code>1234567890.1234567890</code> rounds to <code>1234567890.1234567</code>.</p><h2 id="large-numbers-as-strings" tabindex="-1">Large numbers as strings <a class="header-anchor" href="#large-numbers-as-strings" aria-label="Permalink to “Large numbers as strings”">​</a></h2><p>Keep large numbers as strings if you need exact precision.</p><h2 id="division-follows-the-operand-types" tabindex="-1">Division follows the operand types <a class="header-anchor" href="#division-follows-the-operand-types" aria-label="Permalink to “Division follows the operand types”">​</a></h2><p>Float division like <code>4.0 / 2.0</code> returns a float. Integer division like <code>4 / 2</code> returns an integer.</p><h2 id="follows-ieee-754-like-go" tabindex="-1">Follows IEEE 754 like Go <a class="header-anchor" href="#follows-ieee-754-like-go" aria-label="Permalink to “Follows IEEE 754 like Go”">​</a></h2><p>Overflow produces <code>+Inf</code> or <code>-Inf</code>, values too small to represent underflow to <code>0.0</code>, and invalid operations like <code>+Inf - +Inf</code> produce <code>NaN</code>. These special values are printed as <code>+Inf</code>, <code>-Inf</code>, and <code>NaN</code>.</p><h2 id="non-finite-floats-become-null-in-json" tabindex="-1">Non-finite floats become <code>null</code> in JSON <a class="header-anchor" href="#non-finite-floats-become-null-in-json" aria-label="Permalink to “Non-finite floats become null in JSON”">​</a></h2><p><code>+Inf</code>, <code>-Inf</code>, and <code>NaN</code> are serialized as <code>null</code>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};